gsl_sum_levin_utrunc_workspace = libgslcblas.gsl_sum_levin_utrunc_workspace

def allocate_and_free_workspace(n):
    try:
        workspace = gsl_sum_levin_utrunc_workspace_alloc(n)
        if not workspace:
            return False

    except Exception as e:
        print("Error occurred during allocation:", str(e))
        return False

    try:
        gsl_sum_levin_utrunc_free(workspace)

    except Exception as e:
        print("Error occurred during deallocation:", str(e))
        return False

    return True

