import ctypes
import numpy as np
from scipy.special import factorial

# Load libraries
libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def __call__(self, x):
        return self.func(x)

class GSLIntegrationWorkspace:
    pass

# Define the integrate function
def integrate(function, a, b, epsabs, epsrel, limit, key):
    funcptr = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(function)
    result = np.zeros(1, dtype=np.double)
    error = np.zeros(1, dtype=np.double)
    workspace = GSLIntegrationWorkspace()

    # Define the callback function for GSL
    def callback(x):
        return funcptr(x)

    if key == 0:
        result[0], error[0] = gsl.integrate.qag(callback, a, b, epsabs, epsrel, limit, 6, workspace)
    elif key == 1:
        result[0], error[0] = gsl.integrate.qagse(callback, a, b, epsabs, epsrel, limit, workspace)
    elif key == 2:
        result[0], error[0] = gsl.integrate.qagi(callback, a, b, epsabs, epsrel, limit, workspace)
    elif key == 3:
        result[0], error[0] = gsl.integrate.qagp(callback, a, b, epsabs, epsrel, limit, workspace)
    else:
        raise ValueError("Invalid integration rule key")

    return str(result[0]) + ", " + str(error[0])

# Example usage
if __name__ == "__main__":
    # Define the function to integrate
    def f(x):
        return np.sin(x)

    # Create a GSLFunction object
    func = GSLFunction(f)

    # Compute the integral
    solution = integrate(func, 0.0, np.pi/2, 1e-6, 1e-6, 10000, 0)
    print(solution)

