def apply_givens_qr(Q, R, i, j, c, s):
    M_Q = libgslcblas.create_gsl_matrix(len(Q), len(Q[0]))
    M_R = libgslcblas.create_gsl_matrix(len(R), len(R[0]))

    for row in range(len(Q)):
        for col in range(len(Q[row])):
            if col == i and row == j:
                libgslcblas.extract_matrix(M_Q).contents[col * len(Q[0]) + row] = c
            else:
                libgslcblas.extract_matrix(M_Q).contents[col * len(Q[0]) + row] = Q[row][col]

    for row in range(len(R)):
        for col in range(len(R[row])):
            if col == i and row == j:
                libgslcblas.extract_matrix(M_R).contents[col * len(R[0]) + row] = s
            else:
                libgslcblas.extract_matrix(M_R).contents[col * len(R[0]) + row] = R[row][col]

    libgslcblas.apply_givens_qr(len(Q), len(Q[0]), M_Q, M_R, i, j, c, s)

    Q_modified = [list(libgslcblas.extract_matrix(M_Q).contents[i * len(Q[0]):(i + 1) * len(Q[0])].reshape(-1)) for i in range(len(Q))]
    R_modified = [list(libgslcblas.extract_matrix(M_R).contents[i * len(R[0]):(i + 1) * len(R[0])].reshape(-1)) for i in range(len(R))]

    return Q_modified, R_modified

