class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = libgslcblas.gsl_matrix_alloc(rows, cols)
        self.rows = rows
        self.cols = cols

    def __del__(self):
        libgslcblas.gsl_matrix_free(self.matrix)

def matrix_to_gsl(matrix):
    rows, cols = len(matrix), len(matrix[0])
    m = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            libgslcblas.gsl_matrix_set(m.matrix, i, j, matrix[i][j])
    return m

def gsl_matrix_to_numpy(gsl_matrix):
    rows, cols = int(libgslcblas.gsl_matrix_nrows(gsl_matrix.matrix)), int(libgslcblas.gsl_matrix_ncols(gsl_matrix.matrix))
    result = [[0.0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            result[i][j] = libgslcblas.gsl_matrix_get(gsl_matrix.matrix, i, j)
    return result

def compute_matrix_exponential(matrix, mode):
    rows, cols = len(matrix), len(matrix[0])
    if rows != cols:
        raise ValueError("Input matrix must be square")

    gsl_m = matrix_to_gsl(matrix)
    eigenvec = GSLMatrix(rows, cols)
    diag = GSLMatrix(rows, cols)

    libgslcblas.gsl_eigen_symmv(eigenvec.matrix, diag.matrix, gsl_m.matrix, mode)

