            libgslcblas.gsl_matrix_set(gsl_m.matrix, i, j, libgslcblas.gsl_matrix_get(eigenvec.matrix, i, j) * exp_diag[i][j])

    result = gsl_matrix_to_numpy(gsl_m)
    return result

