class GslRstatQuantileWorkspace:
    def __init__(self):
        self.workspace = ctypes.c_void_p(None)

    def alloc(self):
        self.workspace = gsl.gsl_rstat_quantile_alloc(ctypes.byref(ctypes.c_double(0.0)))
        if not self.workspace:
            raise ValueError('Failed to allocate quantile workspace')

    def reset(self, p):
        result = gsl.gsl_rstat_quantile_reset(self.workspace, ctypes.byref(ctypes.c_double(p)))
        if result != 0:
            raise ValueError('Failed to reset quantile workspace')

    def add(self, x):
        result = gsl.gsl_rstat_quantile_add(self.workspace, ctypes.c_double(x))
        if result != 0:
            raise ValueError('Failed to add value to quantile workspace')

    def get(self):
        quantile = ctypes.c_double(0.0)
        result = gsl.gsl_rstat_quantile_get(self.workspace, ctypes.byref(quantile))
        if result != 0:
            raise ValueError('Failed to retrieve the quantile')
        return quantile.value

    def free(self):
        result = gsl.gsl_rstat_quantile_free(self.workspace)
        if result != 0:
            raise ValueError('Failed to free quantile workspace')

